{"odds.py": """"Implied probability derived from American odds."""

from math import isfinite

__all__ = ["american_probability"]


def _coerce(value):
    """Return *value* as an int or float, else raise ValueError."""
    if isinstance(value, bool):
        raise ValueError("odds must not be a bool")
    if isinstance(value, str):
        text = value.strip()
        if not text:
            raise ValueError("odds must be a numeric string")
        try:
            return float(text)
        except (TypeError, ValueError, OverflowError):
            raise ValueError("odds must be a numeric string")
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return value
    raise ValueError("odds must be an int, float or numeric string")


def american_probability(value):
    """Return the implied probability for the American odds *value*."""
    number = _coerce(value)
    if isinstance(number, float) and not isfinite(number):
        raise ValueError("odds must be finite")
    if abs(number) < 100:
        raise ValueError("odds must have absolute value >= 100")
    if number > 0:
        try:
            return 100.0 / (number + 100)
        except OverflowError:
            return 0.0
    try:
        return (-number) / (-number + 100)
    except OverflowError:
        return 1.0
