import re
from datetime import datetime

from odds import american_probability

__all__ = ["select_latest"]

_FRACTION = re.compile(r"(\.\d{6})\d+")
_OFFSET = re.compile(r"([+-]\d{2})(\d{2})$")


def _parse_aware(stamp):
    """Parse an ISO-8601 timestamp; return an aware datetime or None."""
    if not isinstance(stamp, str):
        return None
    text = stamp.strip()
    if not text:
        return None
    if text[-1] in ("Z", "z"):
        text = text[:-1] + "+00:00"
    text = _FRACTION.sub(r"\1", text)
    text = _OFFSET.sub(r"\1:\2", text)
    try:
        moment = datetime.fromisoformat(text)
    except ValueError:
        return None
    try:
        if moment.utcoffset() is None:
            return None
    except Exception:
        return None
    return moment


def _is_aware(moment):
    """True when *moment* is a timezone-aware datetime."""
    if not isinstance(moment, datetime):
        return False
    try:
        return moment.tzinfo is not None and moment.utcoffset() is not None
    except Exception:
        return False


def select_latest(rows, asof):
    """Return the original eligible row with the latest observed_at.

    Ties on observed_at are broken by the lexicographically smallest id.
    """
    if not _is_aware(asof):
        raise ValueError("asof must be a timezone-aware datetime")
    if rows is None:
        return None
    try:
        iterator = iter(rows)
    except TypeError:
        return None

    best = None
    best_seen = None
    best_id = None

    for row in iterator:
        if not isinstance(row, dict):
            continue
        row_id = row.get("id")
        if not isinstance(row_id, str) or row_id == "":
            continue
        try:
            american_probability(row.get("odds"))
        except (ValueError, TypeError, OverflowError):
            continue
        seen = _parse_aware(row.get("observed_at"))
        if seen is None:
            continue
        expires = _parse_aware(row.get("expires_at"))
        if expires is None:
            continue
        if seen > asof or asof >= expires or seen >= expires:
            continue
        if best_seen is None or seen > best_seen or (seen == best_seen and row_id < best_id):
            best = row
            best_seen = seen
            best_id = row_id

    return best
